import fs, { type FileRef } from "@rcompat/fs";
import p from "pema";
import { MAIN_FOLDER, CONFIG_FILE, PACKAGES_KEY, GLOBAL_CONFIG_PATH } from "#constants";

const configSchema = p({
  harness: p.string,
  [PACKAGES_KEY]: p.array(p.string).optional(),
});

export type Config = {
  harness: string;
  packages: string[];
};

/**
 * Read the project config from `${MAIN_FOLDER}/config.json`.
 * Returns null if the config file does not exist.
 * If the packages array is missing, it defaults to [].
 */
export async function readConfig(
  projectRoot: FileRef,
): Promise<Config | null> {
  const configPath = projectRoot.append(`/${MAIN_FOLDER}/${CONFIG_FILE}`);

  if (!(await fs.exists(configPath))) {
    return null;
  }

  const raw = configSchema.parse(await configPath.json());
  return {
    harness: raw.harness,
    packages: raw.packages ?? [],
  };
}

/**
 * Write the project config to `${MAIN_FOLDER}/config.json`.
 * Creates the `${MAIN_FOLDER}` folder if it doesn't exist.
 */
export async function writeConfig(
  projectRoot: FileRef,
  config: Config,
): Promise<void> {
  const configPath = projectRoot.append(`/${MAIN_FOLDER}/${CONFIG_FILE}`);
  await fs.create(configPath.directory);
  await configPath.write(JSON.stringify(config, null, 2) + "\n");
}

/**
 * Read the global config from `~/.powers/config.json`.
 * Returns { packages: [] } if the file doesn't exist (graceful degradation).
 */
export async function readGlobalConfig(): Promise<{ packages: string[] }> {
  const configPath = fs.ref(GLOBAL_CONFIG_PATH);

  if (!(await fs.exists(configPath))) {
    return { packages: [] };
  }

  const raw = configSchema.parse(await configPath.json());
  return {
    packages: raw.packages ?? [],
  };
}

/**
 * Write the global config to `~/.powers/config.json`.
 * Creates the folder structure if it doesn't exist.
 */
export async function writeGlobalConfig(
  config: { packages: string[] },
): Promise<void> {
  const configPath = fs.ref(GLOBAL_CONFIG_PATH);
  await fs.create(configPath.directory);
  await configPath.write(JSON.stringify(config, null, 2) + "\n");
}

/**
 * Add a package name to the project config's packages array.
 * Does nothing if the package is already listed.
 * Does nothing if the project config doesn't exist.
 */
export async function addPackageToConfig(
  projectRoot: FileRef,
  packageName: string,
): Promise<void> {
  const config = await readConfig(projectRoot);
  if (config === null) return;

  if (!config.packages.includes(packageName)) {
    config.packages.push(packageName);
    await writeConfig(projectRoot, config);
  }
}

/**
 * Remove a package name from the project config's packages array.
 * Does nothing if the package is not listed.
 * Does nothing if the project config doesn't exist.
 */
export async function removePackageFromConfig(
  projectRoot: FileRef,
  packageName: string,
): Promise<void> {
  const config = await readConfig(projectRoot);
  if (config === null) return;

  config.packages = config.packages.filter(p => p !== packageName);
  await writeConfig(projectRoot, config);
}

/**
 * Add a package name to the global config's packages array.
 * Does nothing if the package is already listed.
 */
export async function addPackageToGlobalConfig(
  packageName: string,
): Promise<void> {
  const config = await readGlobalConfig();

  if (!config.packages.includes(packageName)) {
    config.packages.push(packageName);
    await writeGlobalConfig(config);
  }
}

import test from "@rcompat/test";
import fs from "@rcompat/fs";
import runtime from "@rcompat/runtime";
import { readConfig, writeConfig, readGlobalConfig } from "#utils/config";
import { MAIN_FOLDER, CONFIG_FILE } from "#constants";

const root = await runtime.projectRoot();
const testRoot = root.append("/tmp");

async function reset() {
  await testRoot.remove();
  await fs.create(testRoot);
}

test.group("readConfig", () => {
  test.case("should return null when config file does not exist", async assert => {
    await reset();
    await fs.create(testRoot.append(`/${MAIN_FOLDER}`));

    const config = await readConfig(testRoot);
    assert(config).equals(null);

    await testRoot.remove();
  });

  test.case(`should return null when ${MAIN_FOLDER} folder does not exist`, async assert => {
    await reset();

    const config = await readConfig(testRoot);
    assert(config).equals(null);

    await testRoot.remove();
  });

  test.case("should read harness from config file", async assert => {
    await reset();
    await fs.create(testRoot.append(`/${MAIN_FOLDER}`));
    await testRoot
      .append(`/${MAIN_FOLDER}/${CONFIG_FILE}`)
      .write(JSON.stringify({ harness: "pi" }));

    const config = await readConfig(testRoot);
    assert(config?.harness).equals("pi");

    await testRoot.remove();
  });

  test.case("should read packages array from config file", async assert => {
    await reset();
    await fs.create(testRoot.append(`/${MAIN_FOLDER}`));
    await testRoot
      .append(`/${MAIN_FOLDER}/${CONFIG_FILE}`)
      .write(JSON.stringify({ harness: "pi", packages: ["my-pkg", "other-pkg"] }));

    const config = await readConfig(testRoot);
    assert(config?.packages).equals(["my-pkg", "other-pkg"]);

    await testRoot.remove();
  });

  test.case("should return empty packages array when not in config", async assert => {
    await reset();
    await fs.create(testRoot.append(`/${MAIN_FOLDER}`));
    await testRoot
      .append(`/${MAIN_FOLDER}/${CONFIG_FILE}`)
      .write(JSON.stringify({ harness: "pi" }));

    const config = await readConfig(testRoot);
    assert(config?.packages).equals([]);

    await testRoot.remove();
  });
});

test.group("writeConfig", () => {
  test.case("should write config file with harness", async assert => {
    await reset();

    await writeConfig(testRoot, { harness: "claude", packages: [] });

    const configPath = testRoot.append(`/${MAIN_FOLDER}/${CONFIG_FILE}`);
    assert(await fs.exists(configPath)).equals(true);

    const config = await readConfig(testRoot);
    assert(config?.harness).equals("claude");

    await testRoot.remove();
  });

  test.case("should overwrite existing config file", async assert => {
    await reset();
    await writeConfig(testRoot, { harness: "pi", packages: [] });
    await writeConfig(testRoot, { harness: "claude", packages: [] });

    const config = await readConfig(testRoot);
    assert(config?.harness).equals("claude");

    await testRoot.remove();
  });

  test.case("should write config file with packages array", async assert => {
    await reset();

    await writeConfig(testRoot, { harness: "claude", packages: ["my-pkg"] });

    const config = await readConfig(testRoot);
    assert(config?.packages).equals(["my-pkg"]);

    await testRoot.remove();
  });
});

test.group("readGlobalConfig", () => {
  test.case("should return empty packages array when global config does not exist or is missing packages", async assert => {
    const config = await readGlobalConfig();
    assert(config).defined();
    assert(Array.isArray(config.packages)).true();
  });
});

