import fs, { type FileRef } from "@rcompat/fs";
import is from "@rcompat/is";
import { readConfig } from "#utils/config";
import { packageJsonSchema, type PowersProperty } from "#schemas/package";
import power_errors from "#errors/powerErrors";
import {
  MAIN_FOLDER,
  INTERNAL_FOLDER,
  SRC_FOLDER,
  ACTIVE_FOLDER,
  GLOBAL_INTERNAL_PATH,
  MULTI_USE_FOLDER,
  SINGLE_USE_FOLDER,
  PACKAGE_FILE,
  type PowerType,
} from "#constants";

export interface ResolvedPower {
  type: PowerType;
  folder: FileRef;
  packageName: string;
  location: "local" | "global";
}

interface PackageLocation {
  packageName: string;
  packageDir: FileRef;
  powers: PowersProperty;
  location: "local" | "global";
}

/**
 * Resolve a package by name, checking local first then global.
 * Returns null if the package doesn't exist in either location.
 */
async function resolvePackage(
  projectRoot: FileRef,
  packageName: string,
): Promise<PackageLocation | null> {
  // Check local first
  const localDir = projectRoot.append(
    `/${MAIN_FOLDER}/${INTERNAL_FOLDER}/${packageName}`,
  );
  if (await fs.exists(localDir)) {
    const pkgJsonPath = localDir.append(`/${PACKAGE_FILE}`);
    if (await fs.exists(pkgJsonPath)) {
      const pkgJson = packageJsonSchema.parse(await pkgJsonPath.json());
      return {
        packageName,
        packageDir: localDir,
        powers: pkgJson.powers,
        location: "local",
      };
    }
  }

  // Check global
  const globalDir = fs.ref(`${GLOBAL_INTERNAL_PATH}/${packageName}`);
  if (await fs.exists(globalDir)) {
    const pkgJsonPath = globalDir.append(`/${PACKAGE_FILE}`);
    if (await fs.exists(pkgJsonPath)) {
      const pkgJson = packageJsonSchema.parse(await pkgJsonPath.json());
      return {
        packageName,
        packageDir: globalDir,
        powers: pkgJson.powers,
        location: "global",
      };
    }
  }

  return null;
}

/**
 * Find a power by name across all config-listed packages.
 *
 * - Reads the project config's packages array
 * - For each package, resolves its location (local first, then global)
 * - Searches the package's powers property for the requested power name
 * - Local packages are prioritized over global on name collision
 * - Throws not_found if the power doesn't exist in any config-listed package
 * - Throws ambiguous if the same power name is found in multiple local packages
 */
export async function resolvePower(
  root: FileRef,
  name: string,
  type?: PowerType,
): Promise<ResolvedPower> {
  const config = await readConfig(root);

  if (config === null) {
    throw power_errors.not_found(name);
  }

  const matches: ResolvedPower[] = [];

  for (const packageName of config.packages) {
    const pkgLoc = await resolvePackage(root, packageName);
    if (pkgLoc === null) continue;

    const active = pkgLoc.powers.active;

    // Determine which types to search
    const typesToSearch: PowerType[] = type
      ? [type]
      : ["multi-use", "single-use"];

    for (const t of typesToSearch) {
      const typeFolder = t === "multi-use" ? MULTI_USE_FOLDER : SINGLE_USE_FOLDER;
      const powersMap = active[typeFolder as keyof typeof active];

      if (is.defined(powersMap)) {
        // Look for exact power name match (not parent:child entries)
        if (is.defined(powersMap[name])) {
          const instructionPath = powersMap[name][0];
          const powerFolder = pkgLoc.packageDir.append(
            `/${instructionPath}`,
          ).directory;

          matches.push({
            type: t,
            folder: powerFolder,
            packageName: pkgLoc.packageName,
            location: pkgLoc.location,
          });
        }
      }
    }
  }

  if (matches.length === 0) {
    throw power_errors.not_found(name);
  }

  if (matches.length === 1) {
    return matches[0];
  }

  // Multiple matches — prefer local
  const localMatches = matches.filter(m => m.location === "local");

  if (localMatches.length === 1) {
    return localMatches[0];
  }

  if (localMatches.length > 1) {
    // Multiple local packages have the same power name
    throw power_errors.ambiguous(name);
  }

  // Multiple global matches — also ambiguous
  throw power_errors.ambiguous(name);
}

import test from "@rcompat/test";
import fs, { type FileRef } from "@rcompat/fs";
import runtime from "@rcompat/runtime";
import { resolvePower } from "#utils/resolve-power";
import { CodeError } from "@rcompat/error";
import { PowerErrorCode } from "#errors/powerErrors";
import {
  MAIN_FOLDER,
  INTERNAL_FOLDER,
  SRC_FOLDER,
  ACTIVE_FOLDER,
  MULTI_USE_FOLDER,
  SINGLE_USE_FOLDER,
  CONFIG_FILE,
  PACKAGE_FILE,
  KEYWORD_PACKAGE,
} from "#constants";

const root = await runtime.projectRoot();
const testRoot = root.append("/tmp");

async function reset() {
  await testRoot.remove();
  await fs.create(testRoot);
}

async function createPackage(
  projectRoot: FileRef,
  packageName: string,
  powers: { name: string; type: "multi-use" | "single-use" }[] = [],
): Promise<void> {
  const pkgDir = projectRoot.append(
    `/${MAIN_FOLDER}/${INTERNAL_FOLDER}/${packageName}`,
  );
  const srcActive = pkgDir.append(`/${SRC_FOLDER}/${ACTIVE_FOLDER}`);

  await fs.create(srcActive.append(`/${MULTI_USE_FOLDER}`));
  await fs.create(srcActive.append(`/${SINGLE_USE_FOLDER}`));

  const powersProperty: Record<string, Record<string, string[]>> = {
    [MULTI_USE_FOLDER]: {},
    [SINGLE_USE_FOLDER]: {},
  };

  for (const power of powers) {
    const typeFolder = power.type === "multi-use" ? MULTI_USE_FOLDER : SINGLE_USE_FOLDER;
    const powerDir = srcActive.append(`/${typeFolder}/${power.name}`);
    await fs.create(powerDir);
    await powerDir.append("/instructions.json").writeJSON({
      name: power.name,
      description: "test",
      variables: { required: [] },
      intent: [],
      output: { create: [], modify: [] },
    });
    powersProperty[typeFolder][power.name] = [
      `./${SRC_FOLDER}/${ACTIVE_FOLDER}/${typeFolder}/${power.name}/instructions.json`,
    ];
  }

  await pkgDir.append(`/${PACKAGE_FILE}`).writeJSON({
    name: packageName,
    version: "1.0.0",
    description: "test package",
    keywords: [KEYWORD_PACKAGE],
    powers: { active: powersProperty },
  });
}

async function createConfig(
  projectRoot: FileRef,
  packages: string[],
  harness = "claude",
): Promise<void> {
  const configDir = projectRoot.append(`/${MAIN_FOLDER}`);
  await fs.create(configDir);
  await configDir.append(`/${CONFIG_FILE}`).writeJSON({
    harness,
    packages,
  });
}

test.case("resolves a power from a local package", async assert => {
  await reset();
  await createPackage(testRoot, "my-pkg", [{ name: "my-power", type: "multi-use" }]);
  await createConfig(testRoot, ["my-pkg"]);

  const result = await resolvePower(testRoot, "my-power");
  assert(result.type).equals("multi-use");
  assert(result.packageName).equals("my-pkg");
  assert(result.location).equals("local");
  assert(result.folder.name).equals("my-power");

  await testRoot.remove();
});

test.case("resolves a single-use power", async assert => {
  await reset();
  await createPackage(testRoot, "my-pkg", [{ name: "my-power", type: "single-use" }]);
  await createConfig(testRoot, ["my-pkg"]);

  const result = await resolvePower(testRoot, "my-power");
  assert(result.type).equals("single-use");
  assert(result.packageName).equals("my-pkg");

  await testRoot.remove();
});

test.case("throws not_found when power is not in any config-listed package", async assert => {
  await reset();
  await createPackage(testRoot, "my-pkg", [{ name: "my-power", type: "multi-use" }]);
  await createConfig(testRoot, ["my-pkg"]);

  let threw;
  try {
    await resolvePower(testRoot, "missing");
  } catch (e: unknown) {
    assert(e instanceof CodeError).true();
    threw = (e as CodeError).code;
  }
  assert(threw).equals(PowerErrorCode.not_found);

  await testRoot.remove();
});

test.case("throws not_found when package is in config but missing from disk", async assert => {
  await reset();
  await createConfig(testRoot, ["missing-pkg"]);

  let threw;
  try {
    await resolvePower(testRoot, "any-power");
  } catch (e: unknown) {
    assert(e instanceof CodeError).true();
    threw = (e as CodeError).code;
  }
  assert(threw).equals(PowerErrorCode.not_found);

  await testRoot.remove();
});

test.case("resolves from second package when not in first", async assert => {
  await reset();
  await createPackage(testRoot, "pkg-a", [{ name: "power-a", type: "multi-use" }]);
  await createPackage(testRoot, "pkg-b", [{ name: "power-b", type: "multi-use" }]);
  await createConfig(testRoot, ["pkg-a", "pkg-b"]);

  const result = await resolvePower(testRoot, "power-b");
  assert(result.packageName).equals("pkg-b");

  await testRoot.remove();
});

test.case("throws ambiguous when same power name in multiple local packages", async assert => {
  await reset();
  await createPackage(testRoot, "pkg-a", [{ name: "shared", type: "multi-use" }]);
  await createPackage(testRoot, "pkg-b", [{ name: "shared", type: "multi-use" }]);
  await createConfig(testRoot, ["pkg-a", "pkg-b"]);

  let threw;
  try {
    await resolvePower(testRoot, "shared");
  } catch (e: unknown) {
    assert(e instanceof CodeError).true();
    threw = (e as CodeError).code;
  }
  assert(threw).equals(PowerErrorCode.ambiguous);

  await testRoot.remove();
});

test.case("disambiguates by type when same power in both types in same package", async assert => {
  await reset();
  await createPackage(testRoot, "my-pkg", [
    { name: "shared", type: "multi-use" },
    { name: "shared", type: "single-use" },
  ]);
  await createConfig(testRoot, ["my-pkg"]);

  const result = await resolvePower(testRoot, "shared", "multi-use");
  assert(result.type).equals("multi-use");

  await testRoot.remove();
});

test.case("throws not_found when config has no packages", async assert => {
  await reset();
  await createPackage(testRoot, "my-pkg", [{ name: "my-power", type: "multi-use" }]);
  await createConfig(testRoot, []);

  let threw;
  try {
    await resolvePower(testRoot, "my-power");
  } catch (e: unknown) {
    assert(e instanceof CodeError).true();
    threw = (e as CodeError).code;
  }
  assert(threw).equals(PowerErrorCode.not_found);

  await testRoot.remove();
});

